Definition credval (A : astate) (c : Z) : Z :=
  match a_active A c with
  | [g] => Z.min (2^20) (count_idle (slots_of A g) * (16 * size_class c))
  | _ => 0
  end.

Definition pot (A : astate) : Z := zsum (credval A) classes.

